s_w_drg_c_b		="Linha de relâmpago"
s_w_drg_c_g		="Cone de gás corrosivo (ácido)"
s_w_drg_c_r		="Cone de fogo"
s_w_drg_c_w		="Cone de frio"
s_w_drg_m_brs	="Linha de fogo"
s_w_drg_m_brz	="Linha de relâmpago"
s_w_drg_m_cpr	="Linha de ácido"
